local a=np.transpose(base,{2,3,1})
local ok,result=pcall(function()return np.iscomplex(a)end)
assert(ok==true,"iscomplex/bool(2, 3, 4)/permuted/tolNone: acceptance"..": "..tostring(result))
eq(result:tolist(),{{{false,false},{false,false},{false,false},{false,false}},{{false,false},{false,false},{false,false},{false,false}},{{false,false},{false,false},{false,false},{false,false}}},"iscomplex/bool(2, 3, 4)/permuted/tolNone: initial: values")
eq(result.shape,{3,4,2},"iscomplex/bool(2, 3, 4)/permuted/tolNone: initial: shape")
eq(result.strides,{8,2,1},"iscomplex/bool(2, 3, 4)/permuted/tolNone: initial: strides")
eq(result.dtype,"bool","iscomplex/bool(2, 3, 4)/permuted/tolNone: initial: dtype")
local write_ok=pcall(function()np.copyto(result,np.array(true,"bool"),"unsafe")end)
eq(write_ok,true,"iscomplex/bool(2, 3, 4)/permuted/tolNone: writable")
eq(result:tolist(),{{{true,true},{true,true},{true,true},{true,true}},{{true,true},{true,true},{true,true},{true,true}},{{true,true},{true,true},{true,true},{true,true}}},"iscomplex/bool(2, 3, 4)/permuted/tolNone: after write: values")
