eq(a.strides,{4,1,12},"iscomplex/bool(2, 3, 4)/permuted/tolNone: input after write: strides")
eq(a.dtype,"bool","iscomplex/bool(2, 3, 4)/permuted/tolNone: input after write: dtype")
