eq(base.strides,{12,4,1},"iscomplex/bool(2, 3, 4)/permuted/tolNone: backing after write: strides")
eq(base.dtype,"bool","iscomplex/bool(2, 3, 4)/permuted/tolNone: backing after write: dtype")
cases=cases+1
end
