eq(base.dtype,"complex256","iscomplexobj/complex256(4,)/base/tolNone: backing after write: dtype")
cases=cases+1
end
end
chunk()
end
assert(cases==2652)
print("predicates112: "..cases.." cases; "..checks.." checks passed")
